cat > src/password.js <<'EOF'
import { randomBytes, scrypt, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";

const scryptAsync = promisify(scrypt);
const KEYLEN = 64;

export function validatePassword(p) {
  const reasons = [];
  if (typeof p !== "string" || p.length < 10) reasons.push("Password must be at least 10 characters");
  if (typeof p !== "string" || !/[A-Z]/.test(p)) reasons.push("Password must contain an uppercase letter");
  if (typeof p !== "string" || !/[a-z]/.test(p)) reasons.push("Password must contain a lowercase letter");
  if (typeof p !== "string" || !/\d/.test(p)) reasons.push("Password must contain a digit");
  return { ok: reasons.length === 0, reasons };
}

export async function hashPassword(p) {
  const salt = randomBytes(16).toString("hex");
  const hash = await scryptAsync(p, salt, KEYLEN);
  return `${salt}:${hash.toString("hex")}`;
}

export async function verifyPassword(p, stored) {
  const [salt, hash] = String(stored).split(":");
  if (!salt || !hash) return false;
  const expected = Buffer.from(hash, "hex");
  const actual = await scryptAsync(p, salt, expected.length);
  return timingSafeEqual(actual, expected);
}
EOF
cat > src/users.js <<'EOF'
import { randomUUID } from "node:crypto";
import { normalizeEmail, validateEmail } from "./email.js";
import { hashPassword, validatePassword, verifyPassword } from "./password.js";

export class InvalidCredentials extends Error {
  constructor(message = "Invalid credentials") {
    super(message);
    this.name = "InvalidCredentials";
  }
}

export class UserStore {
  #byEmail = new Map();

  async register(email, password) {
    const e = validateEmail(email);
    if (!e.ok) throw new Error(e.reason);
    const p = validatePassword(password);
    if (!p.ok) throw new Error(p.reasons.join("; "));
    const key = normalizeEmail(email);
    if (this.#byEmail.has(key)) throw new Error("Email already registered");
    const user = { id: randomUUID(), email: key, hash: await hashPassword(password) };
    this.#byEmail.set(key, user);
    return { id: user.id, email: key };
  }

  async login(email, password) {
    const user = typeof email === "string" ? this.#byEmail.get(normalizeEmail(email)) : undefined;
    if (!user || !(await verifyPassword(String(password), user.hash))) throw new InvalidCredentials();
    return { id: user.id, email: user.email };
  }
}
EOF
cat > src/index.js <<'EOF'
export * from "./email.js";
export * from "./password.js";
export * from "./users.js";
EOF
cat > test/password.test.js <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";

import { hashPassword, validatePassword, verifyPassword } from "../src/password.js";

test("validatePassword accepts a strong password", () => {
  assert.deepEqual(validatePassword("Abcdefgh12"), { ok: true, reasons: [] });
});

for (const [name, p] of [
  ["short", "Abc123456"],
  ["without uppercase", "abcdefgh12"],
  ["without lowercase", "ABCDEFGH12"],
  ["without digit", "Abcdefghij"],
]) {
  test(`validatePassword rejects ${name}`, () => {
    const r = validatePassword(p);
    assert.equal(r.ok, false);
    assert.equal(r.reasons.length, 1);
  });
}

test("validatePassword reports every failure", () => {
  assert.equal(validatePassword("").reasons.length, 4);
});

test("hashPassword uses salt:hash hex and random salt", async () => {
  const a = await hashPassword("Abcdefgh12");
  assert.match(a, /^[0-9a-f]+:[0-9a-f]+$/);
  assert.notEqual(a, await hashPassword("Abcdefgh12"));
});

test("verifyPassword accepts right and rejects wrong password or malformed hash", async () => {
  const h = await hashPassword("Abcdefgh12");
  assert.equal(await verifyPassword("Abcdefgh12", h), true);
  assert.equal(await verifyPassword("Abcdefgh13", h), false);
  assert.equal(await verifyPassword("Abcdefgh12", "garbage"), false);
});
EOF
cat > test/users.test.js <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";

import { InvalidCredentials, UserStore } from "../src/users.js";

const PW = "Abcdefgh12";

test("register normalizes email and returns id/email only", async () => {
  const u = await new UserStore().register("  Bob@Example.com ", PW);
  assert.deepEqual(Object.keys(u).sort(), ["email", "id"]);
  assert.equal(u.email, "bob@example.com");
});

test("register rejects invalid email", async () => {
  await assert.rejects(new UserStore().register("nope", PW), /@/);
});

test("register rejects weak password", async () => {
  await assert.rejects(new UserStore().register("a@b.co", "weak"), /Password/);
});

test("register rejects duplicates regardless of case", async () => {
  const s = new UserStore();
  await s.register("a@b.co", PW);
  await assert.rejects(s.register("A@B.CO", PW), /already registered/);
});

test("login returns the user with any email casing", async () => {
  const s = new UserStore();
  const u = await s.register("a@b.co", PW);
  assert.deepEqual(await s.login(" A@B.co", PW), u);
});

test("login throws InvalidCredentials for wrong password and unknown user", async () => {
  const s = new UserStore();
  await s.register("a@b.co", PW);
  await assert.rejects(s.login("a@b.co", "Wrongpass12"), InvalidCredentials);
  await assert.rejects(s.login("x@b.co", PW), InvalidCredentials);
});
EOF
npm test 2>&1 | grep -E "^(not ok|# (tests|pass|fail))"

